input.command:
cd /work/packages/zod/src; cat >> v4/classic/tests/intersection.test.ts <<'E'

test("intersection strips __proto__ when merging", () => {
  const a = z.intersection(z.object({ name: z.string() }), z.unknown());
  expect(a.parse(JSON.parse('{"__proto__":{"isAdmin":true},"name":"alice"}'))).toEqual({ name: "alice" });

  const b: any = z.intersection(z.record(z.string(), z.unknown()), z.any()).parse(JSON.parse('{"__proto__":{},"a":1}'));
  expect(b).toEqual({ a: 1 });
  expect(Object.prototype.hasOwnProperty.call(b, "__proto__")).toBe(false);
});
E
